package binlogviz

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"binlogviz/internal/jsonschema"
)

// docs/examples holds the sample reports the quickstart points operators at.
// They are generated by a real analyze of the committed fixture and must not
// drift from what the binary prints today (#439): both must be byte-identical
// to a fresh run, and the JSON must satisfy the shipped analyze schema.
// UPDATE_EXAMPLES=1 regenerates both files.
func TestExampleOutputsMatchFreshRun(t *testing.T) {
	forceEnglishRuntimeOutput(t)
	root := repoRoot(t)
	t.Chdir(root)
	rel := "cmd/binlogviz/testdata/minimal.binlog"
	for _, tc := range []struct {
		format string
		file   string
	}{
		{"json", "analyze-output.json"},
		{"text", "analyze-output.txt"},
	} {
		code, stdout, stderr := runRoot(t, "analyze", rel, "--format", tc.format)
		if code != 0 {
			t.Fatalf("analyze --format %s: exit %d: %s", tc.format, code, stderr)
		}
		path := filepath.Join(root, "docs", "examples", tc.file)
		if os.Getenv("UPDATE_EXAMPLES") == "1" {
			if err := os.WriteFile(path, []byte(stdout), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		checked, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("read %s (UPDATE_EXAMPLES=1 rewrites it): %v", path, err)
		}
		if !bytes.Equal(checked, []byte(stdout)) {
			t.Errorf("docs/examples/%s differs from a fresh run; UPDATE_EXAMPLES=1 regenerates it", tc.file)
		}
		if tc.format == "json" {
			var inst any
			if err := json.Unmarshal(checked, &inst); err != nil {
				t.Fatal(err)
			}
			if err := jsonschema.Validate(readPublishedSchema(t, root, "analyze"), inst); err != nil {
				t.Errorf("docs/examples/%s fails docs/schema/analyze.json: %v", tc.file, err)
			}
		}
	}
}
